#!/usr/bin/env python3
"""Persist exact recoverable Checkpoint 2 build defects in the recovery record."""
from pathlib import Path

path = Path(__file__).with_name("build_checkpoint2_recovery.py")
text = path.read_text(encoding="utf-8")
marker = '''    dedup: dict[str, dict[str, Any]] = {}\n'''
if marker not in text:
    raise SystemExit("Recovery-event insertion marker not found")
insert = '''    events.extend([\n        {\n            "event_number": 91,\n            "event_code": "V3-CP4-S1-REC-SCHEMA-AWARE-UPSERT-CORRECTED",\n            "occurred_at": NOW,\n            "failed_step": "Insert Response 65 into the copied SQLite response-reconciliation table.",\n            "exact_error_or_reason": "sqlite3.IntegrityError: NOT NULL constraint failed: thread_response_reconciliation_cp3.branch_id. The generic upsert helper had incorrectly removed every field ending in _id, including required business fields branch_id and source_id.",\n            "intact_artifacts": "Complete Restore Through Response 64, frozen Section 3 release, accepted predecessor, and the uncommitted copied database remained intact.",\n            "recovery_action": "Replaced suffix-based filtering with schema-aware exclusion of only actual primary-key columns, then restarted the transaction from a fresh copied database.",\n            "validation_result": "Response 65 inserted exactly once; SQLite integrity ok; zero foreign-key violations.",\n            "data_quality_effect": "None; the failed transaction was rolled back.",\n            "next_checkpoint": "Continue Checkpoint 2 synchronization.",\n        },\n        {\n            "event_number": 92,\n            "event_code": "V3-CP4-S1-REC-MERGED-CELL-AUTOSIZE-CORRECTED",\n            "occurred_at": NOW,\n            "failed_step": "Autosize the new workbook dashboard columns.",\n            "exact_error_or_reason": "AttributeError: 'MergedCell' object has no attribute 'column_letter'. The title merge made the first object in one column a MergedCell.",\n            "intact_artifacts": "The copied database synchronization had passed, and the source workbook and frozen project remained unchanged.",\n            "recovery_action": "Replaced cell-derived column letters with index-based get_column_letter enumeration and rebuilt the workbook from the accepted source workbook.",\n            "validation_result": "All 35 accepted sheets preserved; seven current Section 4 sheets added; 42 sheets total; zero formula-error tokens.",\n            "data_quality_effect": "None.",\n            "next_checkpoint": "Continue application synchronization.",\n        },\n        {\n            "event_number": 93,\n            "event_code": "V3-CP4-S1-REC-NATIVE-APPLICATION-CONFIGURATION-ADOPTED",\n            "occurred_at": NOW,\n            "failed_step": "Verify a hard-coded Section 4 database filename inside human_pathogen_app.py.",\n            "exact_error_or_reason": "RuntimeError: application_database_reference_missing. Inspection showed that the resolver is intentionally database-agnostic and requires a --db command-line argument; forcing a filename substitution would have been brittle and incorrect.",\n            "intact_artifacts": "The application source, 95 direct legacy tests, 44 loopback HTTP/security tests, copied database, workbook, and frozen release remained intact.",\n            "recovery_action": "Preserved the resolver byte-for-byte, created a Section 4 launcher/current-state pointer using the native --db interface, reran all 139 legacy assertions, and added 15 direct plus 8 HTTP/security checks against the current database.",\n            "validation_result": "162 total application checks passed; resolver source hash unchanged; non-loopback binding remained rejected.",\n            "data_quality_effect": "None; the correction improved configuration fidelity.",\n            "next_checkpoint": "Build reports and checkpoint package.",\n        },\n        {\n            "event_number": 94,\n            "event_code": "V3-CP4-S1-REC-APPLICATION-QA-AGGREGATE-RESTORED",\n            "occurred_at": NOW,\n            "failed_step": "Generate the human-readable Checkpoint 2 report after expanded application QA.",\n            "exact_error_or_reason": "KeyError: 'test_count'. Application QA had been expanded into legacy_assertion_count, current_direct_check_count, and current_http_check_count, but the report still requested the former aggregate key.",\n            "intact_artifacts": "All substantive synchronization and QA gates had passed in the disposable copied tree; no accepted file was modified.",\n            "recovery_action": "Added an explicit test_count equal to 139 legacy assertions plus 15 current direct checks plus 8 current HTTP/security checks, then rebuilt reports and the package from a fresh verified base.",\n            "validation_result": "DOCX, searchable PDF, XLSX register, package manifest, checksums, ZIP CRC, and clean-package manifest verification passed.",\n            "data_quality_effect": "None.",\n            "next_checkpoint": "Persist the verified checkpoint recovery data in Google Drive.",\n        },\n    ])\n'''
text = text.replace(marker, insert + marker, 1)
for old, new in [
    ("RECOVERY_EVENTS_85_90.json", "RECOVERY_EVENTS_85_94.json"),
    ("Recovery Events 85–90", "Recovery Events 85–94"),
    ("Recovery Events 85-90", "Recovery Events 85-94"),
    ("Recovery Events 85–90 synchronized", "Recovery Events 85–94 synchronized"),
]:
    text = text.replace(old, new)
path.write_text(text, encoding="utf-8")
print({"checkpoint2_recoverable_build_events": "91-94 added", "builder": str(path)})
